import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    try:
        n = int(next(it))
    except StopIteration:
        n = 0
    set1 = set()
    for _ in range(n):
        try:
            set1.add(int(next(it)))
        except StopIteration:
            break
    try:
        m = int(next(it))
    except StopIteration:
        m = 0
    set2 = set()
    for _ in range(m):
        try:
            set2.add(int(next(it)))
        except StopIteration:
            break

    inter = set1 & set2
    out = []
    if inter:
        for val in sorted(inter):
            out.append(str(val))
    else:
        out.append("No common elements.")
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
